// Type declarations for the build-time generated resources module.
// The actual file (resources.ts) is generated by scripts/build-resources.mjs.
// The files to install are embedded in the installer binary (src-tauri/payload.zip).

export declare const PRODUCT_INFO: {
  readonly mode: string;
  readonly name: string;
  readonly installFolder: string;
  readonly uiExeName: string;
  readonly serviceName: string;
  readonly serviceDescription: string;
  readonly version: string;
  readonly publisher: string;
};

export type ProductInfo = typeof PRODUCT_INFO;
